const b = $input.first().json.body || $input.first().json;
const marca = b.marca || {};
const idea = b.idea || {};
const conIngles = (marca.idiomas || 'es').indexOf('en') >= 0;
const captionPrompt = `Eres community manager de "${marca.nombre}".\n`
  + `Voz/tono: ${marca.voz || ''}. Guia de estilo: ${marca.guiaEstilo || ''}.\n`
  + `Tema del post: "${idea.titulo}". ${idea.descripcion || ''}\n`
  + `Escribe el caption para Instagram/Facebook, atractivo y fiel a la marca.\n`
  + (conIngles ? 'Incluye tambien version en ingles.\n' : '')
  + `Sugiere de 8 a 15 hashtags (incluye si aplican: ${marca.hashtagsBase || ''}).\n`
  + `Responde SOLO JSON: {"es":"...",` + (conIngles ? ` "en":"...",` : ``) + ` "hashtags":["#..."]}.`;
const imagePrompt = `${b.promptImagen || idea.titulo}. Estilo de marca: ${marca.guiaEstilo || ''}. Alta calidad, apto para redes, formato cuadrado 1:1.`;
return [{ json: { captionPrompt, imagePrompt, jobId: b.jobId, postId: b.postId, callbackUrl: b.callbackUrl } }];

const prep = $('Preparar').first().json;
let text=''; try { text = $json.candidates[0].content.parts[0].text || ''; } catch(e){}
let cap={}; try { cap = JSON.parse(text); } catch(e){ const m=text.match(/\{[\s\S]*\}/); if(m){ try{cap=JSON.parse(m[0]);}catch(e2){} } }
const hashtags = Array.isArray(cap.hashtags) ? cap.hashtags : [];
return [{ json: { es: cap.es||cap.ES||'', en: cap.en||cap.EN||'', hashtags, imagePrompt: prep.imagePrompt, jobId: prep.jobId, postId: prep.postId, callbackUrl: prep.callbackUrl } }];

const cap = $('Parsear Caption').first().json;
let dataBase64=''; let mime='image/png';
try {
  const parts = $json.candidates[0].content.parts || [];
  const img = parts.find(p => p.inlineData || p.inline_data);
  if (img) { const d = img.inlineData || img.inline_data; dataBase64 = d.data; mime = d.mimeType || d.mime_type || 'image/png'; }
} catch(e) {}
const assets = dataBase64 ? [{ orden:1, tipo:'imagen', dataBase64, mime, modelo:'gemini-3.1-flash-image', prompt: cap.imagePrompt }] : [];
return [{ json: { _callbackUrl: cap.callbackUrl, jobId: cap.jobId, postId: cap.postId, estado: assets.length ? 'ok' : 'error', caption: { es: cap.es, en: cap.en }, hashtags: cap.hashtags, assets, modelo: 'gemini-flash-latest', error: assets.length ? null : 'No se genero imagen' } }];
